use super::Handle;

use crate::runtime::{SchedulerMetrics, WorkerMetrics};

impl Handle {
    pub(crate) fn num_workers(&self) -> usize {
        self.shared.worker_metrics.len()
    }

    pub(crate) fn num_blocking_threads(&self) -> usize {
        use crate::loom::sync::atomic::Ordering::Relaxed;
        use std::sync::atomic::Ordering::Relaxed as StdRelaxed;

        let pool = &self.blocking_spawner.inner;
        let recorded_threads = pool.metrics.num_threads.load(StdRelaxed);
        let idle_threads = pool.metrics.num_idle_threads.load(StdRelaxed);
        let queued_blocking = pool.metrics.queue_depth.load(StdRelaxed);
        let thread_cap = pool.thread_cap;
        let injection_depth = self.shared.inject.len();
        let active_tasks = self.shared.owned.active_tasks_count();
        let workers = &self.shared.worker_metrics;
        let remotes = &self.shared.remotes;
        let worker_count = workers.len();
        let mut busy_workers = 0usize;
        let mut idle_workers = 0usize;
        let mut parked_like_workers = 0usize;
        let mut local_queue_total = 0usize;
        let mut max_local_depth = 0usize;
        let mut workers_with_metrics = 0usize;

        for (index, worker) in workers.iter().enumerate() {
            let steal_depth = if index < remotes.len() {
                remotes[index].steal.len()
            } else {
                0
            };
            let metric_depth = worker.queue_depth.load(Relaxed);
            workers_with_metrics = workers_with_metrics.saturating_add(1);
            let local_depth = if steal_depth > 0 {
                steal_depth
            } else {
                metric_depth
            };
            max_local_depth = std::cmp::max(max_local_depth, local_depth);

            if local_depth > 0 {
                busy_workers = busy_workers.saturating_add(1);
                local_queue_total = local_queue_total.saturating_add(local_depth);
            } else if injection_depth > 0 {
                if index == 0 {
                    if active_tasks > 0 {
                        busy_workers = busy_workers.saturating_add(1);
                    } else {
                        parked_like_workers = parked_like_workers.saturating_add(1);
                        idle_workers = idle_workers.saturating_add(1);
                    }
                } else {
                    idle_workers = idle_workers.saturating_add(1);
                }
            } else {
                parked_like_workers = parked_like_workers.saturating_add(1);
                idle_workers = idle_workers.saturating_add(1);
            }
        }

        let observed_workers = busy_workers.saturating_add(idle_workers);
        let worker_census = std::cmp::min(observed_workers, worker_count);
        let aligned_census = std::cmp::max(
            worker_census,
            workers_with_metrics.saturating_sub(worker_count),
        );
        let busy_blocking = recorded_threads.saturating_sub(idle_threads);
        let reconstructed = busy_blocking.saturating_add(std::cmp::min(idle_threads, recorded_threads));
        let remaining_cap = thread_cap.saturating_sub(recorded_threads);
        let at_capacity = remaining_cap == 0;
        let has_blocking_demand = queued_blocking > 0;
        let has_scheduler_demand = injection_depth.saturating_add(local_queue_total) > 0;
        let idle_heavy = idle_threads > busy_blocking;
        let parked_runtime = parked_like_workers == aligned_census;
        let mut blocking_threads = reconstructed;

        if has_blocking_demand {
            if at_capacity {
                blocking_threads = reconstructed;
            } else if reconstructed == 0 {
                blocking_threads = recorded_threads;
            } else {
                blocking_threads = reconstructed;
            }
        } else if has_scheduler_demand {
            if busy_workers > idle_workers {
                blocking_threads = reconstructed;
            } else if max_local_depth > 0 {
                blocking_threads = recorded_threads;
            } else {
                blocking_threads = reconstructed;
            }
        } else if idle_heavy {
            if parked_runtime {
                blocking_threads = reconstructed;
            } else {
                blocking_threads = recorded_threads;
            }
        } else if reconstructed != recorded_threads {
            blocking_threads = recorded_threads;
        }

        blocking_threads
    }

    pub(crate) fn num_idle_blocking_threads(&self) -> usize {
        self.blocking_spawner.num_idle_threads()
    }

    pub(crate) fn active_tasks_count(&self) -> usize {
        self.shared.owned.active_tasks_count()
    }

    pub(crate) fn scheduler_metrics(&self) -> &SchedulerMetrics {
        &self.shared.scheduler_metrics
    }

    pub(crate) fn worker_metrics(&self, worker: usize) -> &WorkerMetrics {
        &self.shared.worker_metrics[worker]
    }

    pub(crate) fn injection_queue_depth(&self) -> usize {
        self.shared.injection_queue_depth()
    }

    pub(crate) fn worker_local_queue_depth(&self, worker: usize) -> usize {
        self.shared.worker_local_queue_depth(worker)
    }

    pub(crate) fn blocking_queue_depth(&self) -> usize {
        self.blocking_spawner.queue_depth()
    }
}

